def calculate_set_value(pattern):
    queue = deque([''])
    total_value = 0
    while queue:
        current_pattern = queue.popleft()
        if len(current_pattern) == len(pattern):
            total_value += calculate_walk_value(current_pattern)
        else:
            for move in ['L', 'R', 'P']:
                new_pattern = current_pattern + move
                if '*' in new_pattern:
                    continue
                queue.append(new_pattern)
    return total_value

