from functools import lru_cache

@lru_cache(None)
def calculate_value(path):
    if not path:
        return 1
    if path[0] == 'L':
        return 2 * calculate_value(path[1:])
    elif path[0] == 'R':
        return 2 * calculate_value(path[1:]) + 1
    else:
        return calculate_value('L' + path[1:]) + calculate_value('R' + path[1:]) + calculate_value('P' + path[1:])

