def solve(s):
    @lru_cache(None)
    def dfs(i, current_value):
        if i == len(s):
            return current_value
        if s[i] == 'L':
            return dfs(i + 1, current_value * 2)
        elif s[i] == 'R':
            return dfs(i + 1, current_value * 2 + 1)
        elif s[i] == 'P':
            return dfs(i + 1, current_value)
        else:
            return dfs(i + 1, current_value * 2) + dfs(i + 1, current_value * 2 + 1)

    return dfs(0, 1)

