import sys
from itertools import product

def calculate_walk_value(walk):
    current_node = 1
    for move in walk:
        if move == 'L':
            current_node *= 2
        elif move == 'R':
            current_node = current_node * 2 + 1
    return current_node

def expand_wildcard(walk):
    wildcard_indices = [i for i, char in enumerate(walk) if char == '*']
    if not wildcard_indices:
        yield walk
    else:
        for combination in product('LRP', repeat=len(wildcard_indices)):
            expanded_walk = list(walk)
            for idx, move in zip(wildcard_indices, combination):
                expanded_walk[idx] = move
            yield ''.join(expanded_walk)

def calculate_set_value(walk_set):
    total_value = 0
    for expanded_walk in expand_wildcard(walk_set):
        total_value += calculate_walk_value(expanded_walk)
    return total_value

